import os
import textwrap
from tempfile import NamedTemporaryFile

import viktor as vkt
from viktor import Color, TableCell

import ifcopenshell
import ifcopenshell.util.element


# --------------------------------------------------------------------------------------
# Notes
# - This app checks IfcWindow and IfcDoor for three performance properties:
#   1) Thermal transmittance (U-value)
#   2) Acoustic rating
#   3) Fire resistance / fire rating
# - IFC authoring tools can use different property names; the app searches for a list of
#   aliases (configurable in the UI).
#
# requirements (add to requirements.txt in your app folder):
#   viktor-sdk
#   ifcopenshell
# --------------------------------------------------------------------------------------


def _get_uploaded_ifc_file(params) -> vkt.File:
    """Return uploaded vkt.File or raise UserError."""
    field_value = params.model.inputs.ifc_file
    if not field_value:
        raise vkt.UserError("Please upload an IFC file.")

    # Some VIKTOR versions return an object with `.file`.
    if hasattr(field_value, "file"):
        ifc_file = field_value.file
    else:
        ifc_file = field_value

    if not isinstance(ifc_file, vkt.File):
        raise vkt.UserError("Invalid IFC upload.")
    return ifc_file


def _open_ifc_model(ifc_file: vkt.File) -> ifcopenshell.file:
    """Open IFC via a temporary file (IfcOpenShell needs a path)."""
    tmp_path = None
    try:
        with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
            tmp.write(ifc_file.getvalue())
            tmp_path = tmp.name
        return ifcopenshell.open(tmp_path)
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                pass


def _split_aliases(text: str) -> list[str]:
    """Split a comma-separated alias list into normalized tokens."""
    if not text:
        return []
    return [t.strip() for t in text.split(",") if t.strip()]


def _get_type_object(element):
    """Try to find the type object for an instance (IfcRelDefinesByType / IsTypedBy)."""
    for rel in getattr(element, "IsTypedBy", []) or []:
        try:
            return rel.RelatingType
        except Exception:
            pass
    for rel in getattr(element, "IsDefinedBy", []) or []:
        if rel.is_a("IfcRelDefinesByType"):
            try:
                return rel.RelatingType
            except Exception:
                pass
    return None


def _merged_psets(element, include_type_psets: bool) -> dict:
    """Return merged pset dict where instance properties override type properties."""
    psets = ifcopenshell.util.element.get_psets(element) or {}

    if include_type_psets:
        type_obj = _get_type_object(element)
        if type_obj is not None:
            type_psets = ifcopenshell.util.element.get_psets(type_obj) or {}
            # merge: start from type, then instance overrides
            merged = {}
            for pset_name, props in type_psets.items():
                merged[pset_name] = dict(props) if isinstance(props, dict) else props
            for pset_name, props in psets.items():
                if pset_name not in merged or not isinstance(merged.get(pset_name), dict) or not isinstance(props, dict):
                    merged[pset_name] = props
                else:
                    merged[pset_name].update(props)
            return merged

    return psets


def _flatten_properties(psets: dict) -> dict[str, object]:
    """Flatten psets -> property name (lower) to first non-empty value."""
    flat = {}
    for _, props in (psets or {}).items():
        if not isinstance(props, dict):
            continue
        for prop_name, val in props.items():
            if val is None:
                continue
            # Skip nested dicts (rare, but can occur)
            if isinstance(val, dict):
                continue
            key = str(prop_name).strip().lower()
            if key and key not in flat:
                flat[key] = val
    return flat


def _find_property_value(flat_props: dict[str, object], aliases: list[str]):
    """Find a value by aliases (exact match first, then substring match)."""
    if not flat_props or not aliases:
        return None

    aliases_l = [a.strip().lower() for a in aliases if a.strip()]

    # Exact
    for a in aliases_l:
        if a in flat_props:
            return flat_props[a]

    # Substring (e.g. "u value" vs "u_value" or "thermaltransmittance")
    for a in aliases_l:
        for k, v in flat_props.items():
            if a in k:
                return v

    return None


def _as_display_value(val) -> str:
    if val is None:
        return ""
    # Try to keep numbers readable, keep strings as-is.
    if isinstance(val, (int, float)):
        return str(val)
    return str(val)


class Parametrization(vkt.Parametrization):
    model = vkt.Page("Model & Checks", views=["ifc_view", "summary", "performance_table"])

    model.inputs = vkt.Section("Inputs")
    model.inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Window/Door Performance Check

            Upload an IFC model and the app will check **all** `IfcWindow` and `IfcDoor` elements for:
            - Thermal transmittance (**U-value**)
            - Acoustic rating
            - Fire resistance / fire rating

            The results table is **color-coded**:
            - **Green**: all required values are present
            - **Red**: one or more required values are missing

            Because IFC authoring tools use different property naming conventions, you can adjust the
            property name aliases below.
            """
        )
    )

    model.inputs.ifc_file = vkt.FileField("IFC file", file_types=[".ifc"])
    model.inputs.include_type_psets = vkt.BooleanField(
        "Also search type properties (IfcWindowType / IfcDoorType)", default=True
    )

    model.inputs.alias_u = vkt.TextField(
        "U-value property name aliases (comma-separated)",
        default="ThermalTransmittance, UValue, U-Value, UFactor, U-Factor, Uw, HeatTransferCoefficient",
    )
    model.inputs.alias_acoustic = vkt.TextField(
        "Acoustic property name aliases (comma-separated)",
        default="AcousticRating, SoundReductionIndex, SoundRating, Rw, STC, SoundTransmissionClass",
    )
    model.inputs.alias_fire = vkt.TextField(
        "Fire resistance property name aliases (comma-separated)",
        default="FireRating, FireResistanceRating, FireResistanceClass, FireResistance, FireClass",
    )


class Controller(vkt.Controller):
    label = "Window/Door Performance Check"
    parametrization = Parametrization(width=55)

    @vkt.IFCView("IFC Viewer")
    def ifc_view(self, params, **kwargs):
        ifc_file = _get_uploaded_ifc_file(params)
        return vkt.IFCResult(ifc_file)

    @vkt.DataView("Summary")
    def summary(self, params, **kwargs):
        ifc_file = _get_uploaded_ifc_file(params)
        model = _open_ifc_model(ifc_file)

        include_type = bool(params.model.inputs.include_type_psets)
        u_aliases = _split_aliases(params.model.inputs.alias_u)
        a_aliases = _split_aliases(params.model.inputs.alias_acoustic)
        f_aliases = _split_aliases(params.model.inputs.alias_fire)

        windows = model.by_type("IfcWindow") or []
        doors = model.by_type("IfcDoor") or []

        ok_count = 0
        missing_count = 0

        for el in list(windows) + list(doors):
            psets = _merged_psets(el, include_type)
            flat = _flatten_properties(psets)
            u_val = _find_property_value(flat, u_aliases)
            a_val = _find_property_value(flat, a_aliases)
            f_val = _find_property_value(flat, f_aliases)
            row_ok = (u_val is not None) and (a_val is not None) and (f_val is not None)
            ok_count += int(row_ok)
            missing_count += int(not row_ok)

        data = vkt.DataGroup(
            vkt.DataItem("IFC schema", model.schema),
            vkt.DataItem("IfcWindow count", len(windows)),
            vkt.DataItem("IfcDoor count", len(doors)),
            vkt.DataItem("OK (all properties present)", ok_count, status=vkt.DataStatus.SUCCESS if ok_count else vkt.DataStatus.INFO),
            vkt.DataItem(
                "Missing (one or more properties)",
                missing_count,
                status=vkt.DataStatus.ERROR if missing_count else vkt.DataStatus.SUCCESS,
                status_message="Check the table to see which properties are missing.",
            ),
        )
        return vkt.DataResult(data)

    @vkt.TableView("Performance table")
    def performance_table(self, params, **kwargs):
        ifc_file = _get_uploaded_ifc_file(params)
        model = _open_ifc_model(ifc_file)

        include_type = bool(params.model.inputs.include_type_psets)
        u_aliases = _split_aliases(params.model.inputs.alias_u)
        a_aliases = _split_aliases(params.model.inputs.alias_acoustic)
        f_aliases = _split_aliases(params.model.inputs.alias_fire)

        green = Color(198, 239, 206)  # Excel-like green
        red = Color(255, 199, 206)    # Excel-like red

        def cell(value, ok: bool) -> TableCell:
            return TableCell(
                value,
                background_color=green if ok else red,
            )

        rows = []
        elements = (model.by_type("IfcWindow") or []) + (model.by_type("IfcDoor") or [])

        for el in elements:
            psets = _merged_psets(el, include_type)
            flat = _flatten_properties(psets)

            u_val = _find_property_value(flat, u_aliases)
            a_val = _find_property_value(flat, a_aliases)
            f_val = _find_property_value(flat, f_aliases)

            has_u = u_val is not None
            has_a = a_val is not None
            has_f = f_val is not None
            row_ok = has_u and has_a and has_f

            try:
                container = ifcopenshell.util.element.get_container(el)
                storey_name = getattr(container, "Name", "") if container else ""
            except Exception:
                storey_name = ""

            status_text = "OK" if row_ok else "MISSING"

            rows.append(
                [
                    cell(status_text, row_ok),
                    el.is_a(),
                    getattr(el, "Name", "") or "",
                    getattr(el, "GlobalId", "") or "",
                    storey_name or "",
                    cell(_as_display_value(u_val), has_u),
                    cell(_as_display_value(a_val), has_a),
                    cell(_as_display_value(f_val), has_f),
                ]
            )

        headers = [
            "Status",
            "IFC Class",
            "Name",
            "GlobalId",
            "Storey",
            "U-value",
            "Acoustic",
            "Fire",
        ]

        return vkt.TableResult(rows, column_headers=headers)
